import{_ as t,o as p,c as n,a2 as e}from"./chunks/framework.DnrXFDHb.js";const i=JSON.parse('{"title":"Token工厂出海：智算中心的账要重算","description":"","frontmatter":{"title":"Token工厂出海：智算中心的账要重算","updated":"2026-09-04T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/Token工厂出海_智算中心的账要重算.md","filePath":"算电协同/Token工厂出海_智算中心的账要重算.md","lastUpdated":null}'),u={name:"算电协同/Token工厂出海_智算中心的账要重算.md"};function q(r,o,a,s,k,T){return p(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="token-工厂-一度电的生意-和三道绕不过去的坎-优化发布版" tabindex="-1">Token 工厂：一度电的生意，和三道绕不过去的坎（优化发布版） <a class="header-anchor" href="#token-工厂-一度电的生意-和三道绕不过去的坎-优化发布版" aria-label="Permalink to &quot;Token 工厂：一度电的生意，和三道绕不过去的坎（优化发布版）&quot;">​</a></h1><blockquote><p>【发布配置｜粘贴正文前请删除本节】</p><p><strong>推荐标题（TOP1）</strong>：《Token 价格跌破 1 美元，为什么还有人往这个行业里冲？》</p><p>备选 1：《量涨千倍，价崩一半：Token 工厂的三道坎》 备选 2：《Token 工厂：一度电的生意，和三道绕不过去的坎》</p><p><strong>摘要（108 字）</strong>：Token 单价跌破 1 美元，日均调用量却两年涨了上千倍。价格是表象，稼动率才是生死线——这门生意正在从&quot;占资源&quot;变成&quot;做运营&quot;。我用 20 年地产的视角，把这笔账算了一遍。</p></blockquote><hr><p><strong>前言</strong>：我干了 20 年地产，管过基金、做过经营性物业的募投管退，最近几年又扎进电力交易和高压直流供电架构。现在开这个号，就是想用&quot;资产 + 电力&quot;的双重视角，把算电协同这件事讲清楚。本文由 AI 协助整理资料和初稿，但每一个判断——比如我说&quot;Token 工厂的生死线不是电价，是稼动率&quot;——都是我自己的体感。也欢迎您在评论区拍砖和切磋。</p><h2 id="先甩两个打架的数字" tabindex="-1">先甩两个打架的数字 <a class="header-anchor" href="#先甩两个打架的数字" aria-label="Permalink to &quot;先甩两个打架的数字&quot;">​</a></h2><p>8 月 31 日，衡量市场每百万 Token 实际支付均价的 Silicon Data LLM Token Expenditure Index（彭博代码 SDLLMTK）报 <strong>0.97 美元</strong>，是该指数发布以来的最低读数，第一次跌破 1 美元。[1]</p><p>这个指数 5 月的高点还在 2.05 美元。三个月跌去一半多，光 8 月一个月就跌了 29%。[2]</p><p>谁在把价格往下打？有海外资管人士点名：月之暗面 Kimi K3 这类中国开源模型，定价明显低于美国头部实验室，正在把全市场的边际支付意愿往下拽。[1]</p><p>三年前，GPT-4 级别的模型，一百万 Token 的定价还要几十美元。</p><p>同一时间轴的另一头：国家数据局披露，中国日均 Token 调用量从 2024 年初的约 1000 亿，涨到 2025 年底的 100 万亿，2026 年 3 月突破 <strong>140 万亿</strong>——两年，涨了一千多倍。[3]</p><p>量涨千倍，价跌数十倍。这生意，怎么做？</p><p>我干了 20 年地产，看到这组数字的第一反应是：这不就是商业地产里的&quot;客流暴涨、客单价崩盘&quot;吗？商场里人挤人，但每个人只买一瓶水，业主的抽成租金还是上不去。</p><p>但真正让我坐直的，是另一件事——就在这条价格曲线一路向下的同时，四川雅安，一座叫&quot;天绛·白泽&quot;的 Token 工厂，在 8 月末点亮投产了。生产智谱、Kimi、DeepSeek 等主流大模型的满血版 Token，投产当月就开始销售放量，9 月规划产能约 3 万亿 Token，年内还要扩两次产，目标月产能 10 万亿。[4]</p><p>一边是价格在崩，一边是有人在往里冲。</p><p>这个反差，值得捋一捋。</p><h2 id="从-收租-到-联营扣点-token-工厂到底改了什么" tabindex="-1">从&quot;收租&quot;到&quot;联营扣点&quot;：Token 工厂到底改了什么 <a class="header-anchor" href="#从-收租-到-联营扣点-token-工厂到底改了什么" aria-label="Permalink to &quot;从&quot;收租&quot;到&quot;联营扣点&quot;：Token 工厂到底改了什么&quot;">​</a></h2><p>先把话说白。</p><p>传统智算中心的生意，本质上是收租：把 GPU 按卡时租出去，一租一年，跟我把商铺租给品牌方没区别。</p><p>这门生意的好处是简单，坏处是天花板低，而且很脆。行业里公开的数字不太好意思看：未经优化的 GPU 集群，平均利用率只有 <strong>20%–30%</strong>；中小租赁商的毛利率普遍不足 20%。[5]</p><p>为什么这么低？因为你的收入跟&quot;硬件被占用的时间&quot;挂钩，而不是跟&quot;这硬件产出了什么&quot;挂钩。租户的业务一进波谷，你的卡就空转。租金照收，但客户续约时一定跟你砍价。</p><p>Token 工厂换了个计费单位：不按卡时，按 Token。</p><p>这一换，三件事跟着变了。</p><p><strong>第一件，收入从&quot;时间&quot;改成&quot;产出&quot;。</strong> 同一张卡，一天跑 8 小时和跑 20 小时，收入差 2.5 倍。8 月下旬，联想公布过一组数：万全异构智算平台靠 PD 分离、KV Cache 优化、芯模编译优化这一套推理优化，把集群利用率从行业常规的 30% 提到 70% 以上，每百万 Token 的硬件成本压到 1 元以内。[6]</p><p><strong>第二件，客户粘性变了。</strong> 卡时租赁比的是价格，客户随时能搬走。Token 工厂是把 API 嵌进了客户的应用代码和 Agent 工作流里，要搬一次，就得重写一遍调用链路。这跟商业地产里&quot;主力租约&quot;和&quot;散铺短租&quot;的区别是一回事——后者永远在比价，前者到期还会坐下来跟你谈。</p><p><strong>第三件，也是我最想说的：计费单位的改变，把&quot;运营&quot;这件事重新定价了。</strong></p><p>我做地产的时候，商场有两种收租方式。第一种是固定租金，旱涝保收，但涨不上去；第二种是&quot;保底租金 + 营业额抽成&quot;，你要懂品牌、懂动线、懂客流，但商场一旦做起来，业主能吃到增长的红利。</p><p>Token 工厂就是第二种。</p><p>行业调研纪要里现在跑出来的分润结构，大致是工厂侧拿八成、渠道拿两成——渠道消纳能力强的，分成可以往上谈；也有&quot;保底 + 超额五五分成&quot;的做法：市场租金线以内的部分先保资产方，超出的部分对半分。按这个口径测算，传统裸金属出租净利率约 20%，切换到 Token 分成模式后有望提到 40% 左右。[7]</p><p>你看，这就不是什么新词了。这是我熟了二十年的联营扣点。</p><h2 id="一度电能产多少-token-现在没人算得清" tabindex="-1">一度电能产多少 Token？现在没人算得清 <a class="header-anchor" href="#一度电能产多少-token-现在没人算得清" aria-label="Permalink to &quot;一度电能产多少 Token？现在没人算得清&quot;">​</a></h2><p>既然是算电协同，就得回到电。</p><p>我原以为这个问题很简单：一度电进去，多少个 Token 出来。查了一圈，发现这个行业连口径都还没统一——而这件事本身，就是个大问题。</p><p>东吴证券今年 5 月的测算：百万 Token 耗电约 <strong>0.6 度</strong>，折算下来一度电产出约 <strong>167 万 Token</strong>；按国内大模型每百万 Token 平均超过 8 元的定价，成本约 0.2 元（参考风光上网电价）的一度电，能变成 13 元以上的产出。[8]</p><p>另一头，新华社的记者手记援引国内电力机构测算：高强度推理任务下，生成 100 万 Token 平均耗电 <strong>15–20 度</strong>。换算下来一度电只产 5 万–6.7 万 Token，跟东吴的数差了三十倍。[9]</p><p>两份信源都不业余，但结论差了一个数量级。为什么？我捋下来，至少四个变量没人统一：</p><p>算的是输出 Token，还是输入输出合计？含不含 PUE 和制冷？按空载算还是按满载算？跑的是 7B 的小模型，还是 671B 的大家伙？</p><p>这四个变量一动，结果天差地别。</p><p><strong>我的看法是：在&quot;度电 Token 产出&quot;这件事上建立统一口径，是 Token 工厂从概念变成产业的分水岭。</strong> 没有统一计量，就没法定价、没法比选、更没法做资产估值。就像当年商业地产如果没有&quot;建筑面积&quot;和&quot;得房率&quot;的统一口径，租金单价根本没法横向比。</p><p>顺带说一个更反直觉的：在全成本口径下，电费并没有大家想的那么吓人。</p><p>东吴的拆分是：每百万 Token 的成本里，<strong>设备折旧占 50%–75%，电力只占 12%–14%</strong>。[8]</p><p>注意，我说的是<strong>全成本</strong>。如果你只看运营成本（不含折旧），电费占比能到 60%–70%——这也是媒体最爱引用的那个数。[10] 两个数都没错，口径不同而已。</p><p>翻译成地产的话：折旧是房贷，电费是物业费。一套房子每个月的现金支出里，物业费确实占大头；但要算总账，压死你的是房贷。</p><p><strong>所以我的第一个判断是：做 Token 工厂，降电价是加分项，不是生死线。真正的生死线是稼动率——你的卡，一年到头有多少时间在生产 Token。</strong></p><p>不过这里有个时间维度的反转，得提醒一句：随着芯片能效提升、服务器价格下行，折旧占比会逐年下降，电力的占比反而会往上走。今天一成多的电，五年后可能是三成。</p><p>算电协同不是现在不重要，而是它的重要性在往后逐年加码。</p><h2 id="三道坎-不是有卡就能叫-工厂" tabindex="-1">三道坎：不是有卡就能叫&quot;工厂&quot; <a class="header-anchor" href="#三道坎-不是有卡就能叫-工厂" aria-label="Permalink to &quot;三道坎：不是有卡就能叫&quot;工厂&quot;&quot;">​</a></h2><p><strong>第一道坎：稼动率。</strong></p><p>腾讯云解决方案总经理张晋今年 7 月在 MWC 上海&quot;智能数据中心峰会&quot;上给过一个数：国内智算中心 GPU 平均利用率不足 30%。[11]</p><p>原中国电信科技委主任韦乐平说得更直白：国内 280 多个智算中心，GPU 利用率很不均衡，&quot;饱的撑死，饿的饿死&quot;，平均不到 30%。[11]</p><p>中国信通院的数据是，2025 年国内智算共算量约 38 亿卡时，用算量只有 14 亿卡时，用算占比 36.8%。[11]</p><p>三个来源，一个结论：<strong>每投 100 块钱建算力，大概 70 块钱在空转。</strong></p><p>但这不是命运。并行科技对财联社披露，公司 2025 年算力服务营收 10.2 亿元，算力利用率在 90% 到 95% 之间，头部企业订单排期已经到了 2028 年。[11]</p><p>同期，另一边高端算力缺得厉害：信通院数据，2026 年一季度国内 AI 算力需求同比涨 417%，有效供给只涨 128%；工信部披露的口径是，高端训练算力有效供给只能满足不到 47% 的市场需求，缺口约 35%。[12]</p><p>一边 70% 空转，一边 35% 缺口——这在我的老本行里叫&quot;结构性空置&quot;。不是没需求，是你的铺子不对路。</p><p><strong>第二道坎：适配。</strong></p><p>这条最容易被做资产的人忽略。</p><p>雅安那座工厂投产时，官方报道里有一句话我印象很深：一座真正的 Token 工厂要过三重门槛——稳定的算力基础设施、面向主流大模型的适配与推理优化能力、可持续的运营商业化能力。[4] 三条里有两条是&quot;软&quot;的。</p><p>硬的卡大家都买得到，软的功夫买不来。模型不预适配，客户拿到卡也跑不起来，迁移的人力和时间成本会直接把客户劝退。联想那个&quot;利用率从 30% 到 70%&quot;的案例，靠的也不是换卡，是调度平台和推理优化。[6]</p><p>地产类比：毛坯交付和精装带租约交付。房子是同一套，后者出租率高出一大截，因为客户拎包就能开业。Token 工厂卖的不是裸算力，是&quot;能直接跑起来的产能&quot;。</p><p><strong>第三道坎：价格通缩撞上刚性成本。</strong></p><p>这是最要命的一道。</p><p>8 月的数据最刺眼：摩根大通的统计，OpenRouter 平台 Token 使用量环比涨了约 47%，美元支出只涨了约 7%。量在暴涨，钱几乎没动。[2]</p><p>成本端呢？高盛的统计是，五家获评级的超大规模云厂商 2026 年资本开支合计约 <strong>7370 亿美元</strong>，约占其收入的 38%。这笔钱是已经承诺出去的、锁死的。还有一个更冷的信号：2026 年发行的 91 只超大厂债券里，8 月底前已有 78 只跌破发行价——信用市场已经在重新定价了。[2]</p><p>收入端在通缩，成本端在爬坡。这个剪刀差，商业地产在 2019 到 2023 年走过一遍，那时候的说法叫&quot;租金覆盖不了利息&quot;。</p><p>对 Token 工厂来说，它的特殊性在于：<strong>折旧是按时间计的，收入是按产出计的。</strong></p><p>你的卡不管有没有订单，折旧照提；而产出的单价还在往下走。这等于把&quot;空置风险&quot;和&quot;价格风险&quot;同时扛在了自己身上。</p><p>这也是为什么我认为，Token 工厂不是所有玩家都能上的牌桌。它把智算中心从&quot;资产持有&quot;推向了&quot;生产制造&quot;——制造业的命门是产能利用率和单位成本，不是地段和估值倍数。</p><h2 id="一道行业内部还在吵的题-工厂该建在哪" tabindex="-1">一道行业内部还在吵的题：工厂该建在哪？ <a class="header-anchor" href="#一道行业内部还在吵的题-工厂该建在哪" aria-label="Permalink to &quot;一道行业内部还在吵的题：工厂该建在哪？&quot;">​</a></h2><p>这个问题我特意留出来，因为我确实没想透，想听听各位的。</p><p><strong>一边是&quot;往西走&quot;。</strong> 逻辑是电价。西部枢纽的绿电价格能打到 0.3 元/度上下，雅安的水电就在这一档。[4] 政策也在推：2026 年政府工作报告首次提出&quot;实施超大规模智算集群、算电协同等新基建工程&quot;；绿电约束也在收紧——发改委等四部门 2024 年就提出&quot;到 2025 年底国家枢纽节点新建数据中心绿电占比超过 80%&quot;，国家数据局今年 3 月再次明确，要确保枢纽节点新建算力设施绿电应用占比达到 80% 以上。[13]</p><p><strong>另一边是&quot;往东靠&quot;。</strong> 逻辑是时延。前面算过账，全成本口径下电费只占一成多，省下的电费有限；但时延一上去，你的 Token 就卖不上价——同样的卡，放在东部核心城市旁边能卖高价，放到几千公里外可能要打折。</p><p>两边都有数据，都有人押注。</p><p>我目前的倾向是：<strong>这不是一道单选题，而是一道分类题。</strong></p><p>训练、离线批处理、视频渲染这类不挑时延的活儿，可以跟着绿电走，还能当电网的&quot;海绵负荷&quot;用——大风季、丰水期就多开工。而实时对话、Agent 这类要抢毫秒的活儿，必须贴着客户建。</p><p>但这是我的推论，不是结论。如果你在一线做调度，欢迎在评论区拍我。</p><h2 id="往后三年-三个方向" tabindex="-1">往后三年，三个方向 <a class="header-anchor" href="#往后三年-三个方向" aria-label="Permalink to &quot;往后三年，三个方向&quot;">​</a></h2><p><strong>方向一：计价单位还会往下沉一层。</strong></p><p>从&quot;卡时&quot;到&quot;Token&quot;是第一步，下一步是&quot;业务结果&quot;。行业里已经有人在提分级交付：卖算力是一层，卖 Token 是一层，再往上是卖场景化的能力包。</p><p>这件事对做资产的人意义很大。卖卡时的收入不可预测，卖 Token 的收入可测算，卖场景包的收入才可能被资本市场当成&quot;类订阅收入&quot;来给倍数。地产里也这样：散铺租金给 5 个点，带 15 年长约的整栋写字楼，资本化率能低到 4 个点出头。现金流的稳定性，本身就是估值。</p><p><strong>方向二：Token 工厂会成为电力系统最好的&quot;可调节负荷&quot;。</strong></p><p>这是我最兴奋的一点，也是我觉得算电协同真正的增量所在。</p><p>推理任务里有一大类是可以等的：离线批处理、模型后训练、视频渲染、数据清洗。这类任务不看地理位置，只看网络。换句话说，Token 工厂的这部分负荷是可以&quot;追着电价跑&quot;的——电价低、绿电足的时候多开工，电价高、电网紧的时候主动降载。</p><p>比起重卡超充那种必须在固定地点、固定时间出现的负荷，Token 工厂的负荷弹性好得多。它不需要建在充电桩旁边，也不需要用户配合。</p><p>过去我们说&quot;算电协同&quot;，讲的是电力怎么保算力；往后可能要反过来讲——<strong>算力怎么帮电力消纳</strong>。</p><p><strong>方向三：资产会分层，而且分得很快。</strong></p><p>我的判断很直接：未来两年，智算中心的估值会出现剧烈分化。</p><p>跑通稼动率、有稳定 Token 现金流、有长约客户的工厂，会被当成&quot;能产生现金流的经营性资产&quot;来定价，甚至具备被并购、被证券化的可能。跑不通的那批，会变成算力版的&quot;烂尾楼&quot;——账面有资产，现金流为零，每年还要付电费和利息。</p><p>分水岭在哪？就三个数：稼动率、Token 单价、客户合约期。跟当年判断一个商场值多少钱看的是出租率、租金单价和租期，一模一样。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>回到开头那个数字：0.97 美元。</p><p>单看这个数，你会觉得 Token 这门生意没法做了。但把它和另一个数放在一起看——140 万亿的日均调用量——你会发现，崩的不是需求，是定价权。</p><p>Token 工厂真正的意义，不是给算力换个计价单位，而是倒逼这个行业从&quot;占资源&quot;转向&quot;做运营&quot;。占资源这几年已经把钱赚完了。接下来赚的，是稼动率、是调度、是软硬一体的那点笨功夫。</p><p>我干了 20 年地产，见过太多&quot;位置好就躺赢&quot;的故事，也见过太多空置的商场。<strong>算力资产这一轮，位置只是入场券，稼动率才是生死线。</strong></p><p>一个人捋容易钻牛角尖。上面那道&quot;工厂建在哪&quot;的题，我是真没想透，评论区交给大家。</p><hr><p><strong>数据来源</strong></p><p>[1] Silicon Data 官网（SDLLMTK，截至 2026-08-31）；财联社《&quot;词元通缩&quot;发酵！Token 支出指数创下历史新低》（2026-09-02） [2] 高盛 One-Delta 交易台报告（Rich Privorotsky，2026-09）、摩根大通数据中心报告，经华尔街见闻、中财网转述（2026-09-04） [3] 国家数据局（刘烈宏，中国发展高层论坛 2026 年年会，2026-03）；中国银行保险报《两年增长超千倍！Token 消耗破 140 万亿》（2026-08-17） [4] 封面新闻、川观新闻、科技日报：&quot;天绛·白泽&quot;Token 工厂投产报道（2026-08-31 至 09-03） [5] 财经网《算力租赁隐秘江湖：赢家藏在巨头指缝间》（2026-05） [6] 快科技《联想词元工厂：让每一份算力都产出 Token》（2026-08-24） [7] 新浪财经/水晶球财经：Token 工厂分润模式调研纪要（2026-06 至 09） [8] 东吴证券电力研究报告《AI 的中国优势》（2026-05） [9] 新华社《记者手记：AI 时代孕育&quot;词元&quot;经济 一度电如何实现价值逆袭》（2026-04-01） [10] 澎湃新闻《Token 出海：绿电的成本账》（2026-06） [11] 虎嗅《中国智算中心 GPU 利用率不足 30%：70% 算力空转》（2026-07-11，含腾讯云张晋 MWC26 上海演讲、中国信通院卡时数据、并行科技采访）；C114/通信世界网：韦乐平在 2025 云网智联大会的演讲（2025-04） [12] 界面新闻《国内 AI 盛宴透视：从腾讯 528 亿资本开支说起》（2026-08，信通院一季度数据、工信部高端算力缺口口径） [13] 2026 年政府工作报告（2026-03-05）；国家发改委等四部门《数据中心绿色低碳发展专项行动计划》（2024-07）；国家数据局刘烈宏在中国发展高层论坛 2026 年年会的表态（2026-03-23）</p><p><strong>风险提示</strong></p><p>⚠️ Token 价格通缩可能快于成本下降；稼动率提升、分润模式跑通存在不确定性；&quot;度电 Token 产出&quot;等行业计量口径尚未统一，文中跨信源数字仅供对照。本文仅为产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，持续追踪算电协同赛道的政策、产业与资本信号。</p>',100)])])}const l=t(u,[["render",q]]);export{i as __pageData,l as default};
